use crate::aap::caps::state_read;

struct Node;

/// Keys tried in order. The first one that yields at least one URL is used.
const KEYS: [&str; 3] = ["urls", "subscriptions", "feeds"];

fn push_unique(out: &mut Vec<String>, candidate: &str) {
    let url = candidate.trim();
    if url.is_empty() || url.starts_with('#') {
        return;
    }
    if !out.iter().any(|u| u == url) {
        out.push(url.to_string());
    }
}

fn hex4(chars: &mut core::iter::Peekable<core::str::Chars<'_>>) -> Option<u32> {
    let mut v = 0u32;
    for _ in 0..4 {
        let c = chars.next()?;
        v = v * 16 + c.to_digit(16)?;
    }
    Some(v)
}

/// Parse a JSON string literal. The opening quote has already been consumed.
fn parse_json_string(chars: &mut core::iter::Peekable<core::str::Chars<'_>>) -> Option<String> {
    let mut s = String::new();
    loop {
        let c = chars.next()?;
        match c {
            '"' => return Some(s),
            '\\' => {
                let e = chars.next()?;
                match e {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{0008}'),
                    'f' => s.push('\u{000C}'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let hi = hex4(chars)?;
                        let code = if (0xD800..0xDC00).contains(&hi) {
                            if chars.next()? != '\\' || chars.next()? != 'u' {
                                return None;
                            }
                            let lo = hex4(chars)?;
                            if !(0xDC00..0xE000).contains(&lo) {
                                return None;
                            }
                            0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                        } else {
                            hi
                        };
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => return None,
                }
            }
            other => s.push(other),
        }
    }
}

/// Collect every string literal in the first JSON array found in `text`.
fn parse_json_array(text: &str) -> Option<Vec<String>> {
    let start = text.find('[')?;
    let mut chars = text[start + 1..].chars().peekable();
    let mut out = Vec::new();
    loop {
        let c = chars.next()?;
        match c {
            ']' => return Some(out),
            '"' => {
                let s = parse_json_string(&mut chars)?;
                push_unique(&mut out, &s);
            }
            _ => {}
        }
    }
}

fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    if trimmed.starts_with('[') || trimmed.starts_with('{') {
        if let Some(list) = parse_json_array(trimmed) {
            return list;
        }
    }
    let mut out = Vec::new();
    for line in trimmed.lines() {
        let line = line.trim();
        if line.starts_with('#') {
            continue;
        }
        for part in line.split(|c: char| c == ',' || c.is_whitespace()) {
            push_unique(&mut out, part);
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present; with nothing stored we
        // cannot produce a valid output, so fail the node rather than emit one.
        panic!("no subscriptions found in state store");
    }
}

export!(Node);
